class Solution:
    def minInsertions(self, s: str) -> int:
        opens = 0
        insertions = 0
        i = 0
        while i < len(s):
            if s[i] == '(':
                opens += 1
                i += 1
            else:
                if i + 1 < len(s) and s[i + 1] == ')':
                    i += 2
                else:
                    insertions += 1
                    i += 1
                if opens > 0:
                    opens -= 1
                else:
                    insertions += 1
        insertions += opens * 2
        return insertions

